// Request prices from the shared price fetch (HBC+ v1.0).
// Start with a fresh msg.dynamic: the section reads an existing msg.dynamic as the
// request and replaces it with the reply.
msg.dynamic = {};
// Optional: another price source than the Dynamic tab's selection, e.g.
// msg.dynamic.data_source = "Grid Clock";
// Optional: reuse the Dynamic tab's cached prices when still valid (no new fetch).
msg.dynamic_use_cache = true;
// Target for the dynamic link call below (by name, survives a re-import of the Dynamic tab).
msg.target = "Dynamic Fetch from Data Source";
return msg;

// Read the reply of the shared price fetch (HBC+ v1.0).
const d = msg.dynamic || {};
const a = d.data_all || {};
if (d.no_data || !Array.isArray(a.list) || a.list.length === 0) {
    node.status({ fill: 'red', shape: 'ring', text: `no prices (${d.data_source || '?'})` });
    msg.payload = { price_now_ct: null, source: d.data_source, no_data: true };
    return msg;
}
const slotMs = (a.hours / a.datapoints) * 3600000;          // interval length (15 min for quarter-hour prices)
const i = Math.floor((Date.now() - new Date(a.start).getTime()) / slotMs);
const priceNow = (i >= 0 && i < a.list.length) ? a.list[i] : null;   // ct/kWh
msg.payload = {
    price_now_ct: priceNow === null ? null : Math.round(priceNow * 100) / 100,
    average_ct: a.average, min_ct: a.min, max_ct: a.max,
    interval_minutes: slotMs / 60000,
    intervals: a.list.length,
    source: d.data_source,
    from_cache: msg.dynamic_from_cache === true,
    stale: d.stale === true
};
node.status({ fill: d.stale ? 'yellow' : 'green', shape: 'dot',
    text: `${msg.payload.price_now_ct} ct/kWh now (${d.data_source}${d.stale ? ', last prices' : ''})` });
return msg;
